#define main pocketbook_application_main
#include "../../src/main.cpp"
#undef main
#include <QtTest/QTest>
#include <QWebEngineUrlRequestInterceptor>
#include <QWebEngineUrlRequestInfo>
#include <QBuffer>
#include <cassert>
#include <iostream>
class NetworkGuard:public QWebEngineUrlRequestInterceptor{public:bool library=false;int writes=0;using QWebEngineUrlRequestInterceptor::QWebEngineUrlRequestInterceptor;void interceptRequest(QWebEngineUrlRequestInfo &i)override{if(i.requestUrl().path().startsWith("/my-books/"))library=true;if(i.requestMethod()=="POST"||i.requestMethod()=="PUT"||i.requestMethod()=="DELETE")++writes;if(i.requestUrl()!=QUrl("https://www.litres.ru/robots.txt")&&i.requestUrl().scheme()!="blob")i.block(true);}};
int main(int argc,char**argv){CompatAssets::registerScheme();prepareBrowserTrust();QApplication app(argc,argv);const QString mode=argc>1?argv[1]:"yes";QDir root("/mnt/ext1/litres-client");root.mkpath(".");QFile::remove(root.filePath("logged-out"));QFile auth(root.filePath("authenticated"));assert(auth.open(QIODevice::WriteOnly));auth.write("1\n");auth.close();assert(ReaderHistory::remember(root.path(),"42","123","Моя последняя книга"));
 QJsonObject local;local["pending"]=false;local["base"]=QJsonObject{{"version",1},{"xpointer","/1/2/1.0"},{"percent",0}};local["local"]=local["base"];QFile state(root.filePath("native-reader/42/123.json"));assert(state.open(QIODevice::WriteOnly));state.write(QJsonDocument(local).toJson());state.close();
 MainWindow window;window.resize(758,1024);window.show();bool prompted=false;QTimer answer;answer.setInterval(20);QObject::connect(&answer,&QTimer::timeout,[&](){auto *box=qobject_cast<QMessageBox *>(QApplication::activeModalWidget());if(!box)return;assert(mode!="other");assert(box->text().contains("Моя последняя книга"));assert(box->textFormat()==Qt::PlainText);prompted=true;for(auto *b:box->buttons())if(b->text()==(mode=="yes"?"Да":"Нет")){b->click();answer.stop();break;}});answer.start();
 QPushButton *open=nullptr;for(auto *b:window.findChildren<QPushButton *>())if(b->text()=="Литрес"){open=b;break;}assert(open);open->click();auto views=window.findChildren<QWebEngineView *>();assert(!views.isEmpty());auto *profile=views.first()->page()->profile();auto *guard=new NetworkGuard(profile);profile->setRequestInterceptor(guard);
 QImage im(120,180,QImage::Format_RGB32);im.fill(Qt::red);QByteArray png;QBuffer buf(&png);buf.open(QIODevice::WriteOnly);assert(im.save(&buf,"JPEG"));
 QJsonArray nodes{QJsonObject{{"t","p"},{"xp",QJsonArray{1,2}},{"c",QJsonArray{QString::fromUtf8("Первый абзац. ").repeated(150)}}},QJsonObject{{"t","img"},{"xp",QJsonArray{1,3}},{"s","i_001.jpg"}},QJsonObject{{"t","p"},{"xp",QJsonArray{1,4}},{"c",QJsonArray{QString::fromUtf8("Место с другого устройства. ").repeated(30)}}}};
 QJsonObject fixture;fixture["nodes"]=nodes;fixture["user"]=mode=="other"?43:42;fixture["png"]=QString::fromLatin1(png.toBase64());QString source="(function(){var f="+QString::fromUtf8(QJsonDocument(fixture).toJson(QJsonDocument::Compact))+";window.fetch=function(url,options){if(options&&options.method==='POST')throw Error('no writes permitted');var data=null;if(url.indexOf('i_001.jpg')>=0){var raw=atob(f.png),a=new Uint8Array(raw.length);for(var i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);return Promise.resolve({status:200,headers:{get:function(){return a.length;}},arrayBuffer:function(){return Promise.resolve(a.buffer);}});}if(url.indexOf('autobookmark')>=0)data={version:9,xpointer:'/1/4/1.0',percent:23.4};else if(url.endsWith('/users/me'))data={id:f.user};else if(url.endsWith('/arts/123'))data={title:'Проверенная книга',release_file_id:456,art_type:0,is_drm:false,is_free:true};else if(url.endsWith('toc.js'))return Promise.resolve({status:200,text:function(){return Promise.resolve(JSON.stringify({Parts:[{s:0,e:10,xps:[1,1],xpe:[1,9],url:'000.js'}]}));}});else if(url.endsWith('000.js'))return Promise.resolve({status:200,text:function(){return Promise.resolve(JSON.stringify(f.nodes));}});else throw Error('unexpected fixture request');return Promise.resolve({status:200,text:function(){return Promise.resolve(JSON.stringify({status:200,error:null,payload:{data:data}}));}});};})();";
 QWebEngineScript script;script.setName("Synthetic authenticated reader fixture");script.setWorldId(QWebEngineScript::MainWorld);script.setInjectionPoint(QWebEngineScript::DocumentCreation);script.setSourceCode(source);profile->scripts()->insert(script);
 for(int i=0;i<3000;++i){QTest::qWait(20);if(mode!="yes"&&guard->library){assert(prompted==(mode=="no"));assert(guard->writes==0);std::cout<<"PASS "<<mode.toStdString()<<": library chosen; no cross-account history disclosure, no progress writes\n";return 0;}
  for(auto *w:window.findChildren<QWidget *>())if(auto *r=dynamic_cast<NativeReader *>(w)){auto d=r->diagnostics();if(d["failed"].toBool()){std::cerr<<QJsonDocument(d).toJson().constData();assert(false);}if(d["part"].toInt(-1)==0&&d["imagesLoaded"].toInt()==1){assert(mode=="yes"&&prompted);assert(!r->pending());assert(d["line"].toInt()>10);assert(!guard->library&&guard->writes==0);auto last=ReaderHistory::read(root.path(),"42");assert(last["title"]=="Проверенная книга");r->grab().save("/tmp/native-image-ui.png");std::cout<<"PASS Yes: current server bookmark restored over old local position; authenticated binary JPEG transport normalized and rendered PNG; last successful book updated, no real API writes\n";return 0;}}
 }
 std::cerr<<"Timeout in resume UI scenario "<<mode.toStdString()<<" prompted="<<prompted<<" library="<<guard->library<<"\n";return 1;
}
